const BASE = PACKAGE.base ?? '/';
const PREFIX = 'esp32-micropython-lab-app-' + (BASE === '/' ? '' : encodeURIComponent(BASE) + '-');
const CACHE = PREFIX + PACKAGE.build;
const MARKER = BASE + '.lab-offline-ready';
